CREATE TABLE livestock(`id` bigint  UNSIGNED PRIMARY KEY AUTO_INCREMENT,`created_at` timestamp  DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` timestamp  DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP NOT NULL,`enable` TINYINT(1)  NOT NULL  DEFAULT 1 ,`farm_id` bigint  NOT NULL,`farmer_id` bigint  NOT NULL,`species` varchar(255)  NOT NULL COMMENT 'cattle, goat, poultry, buffalo',`breed` varchar(255)  NOT NULL,`quantity` INT  NOT NULL DEFAULT 1,`purchase_price` DECIMAL(12,2)  NOT NULL,`purchase_date` date  NOT NULL,`purpose` varchar(255)  NOT NULL COMMENT 'dairy, meat, breeding, eggs',`expected_roi` DECIMAL(12,2)  NULL COMMENT 'Expected return on investment',`break_even_date` date  NULL,`status` varchar(255)  DEFAULT 'active' COMMENT 'active, sold, deceased',`latitude` DECIMAL(10,8)  NULL COMMENT 'Livestock location GPS latitude (optional, can differ from farm)',`longitude` DECIMAL(11,8)  NULL COMMENT 'Livestock location GPS longitude (optional)',`pincode` varchar(10)  NULL COMMENT 'Livestock location postal code',`state` varchar(100)  NULL COMMENT 'Livestock location state',`district` varchar(100)  NULL COMMENT 'Livestock location district',`village` varchar(100)  NULL COMMENT 'Livestock location village/VPO',`address_line` varchar(255)  NULL COMMENT 'Full livestock location address')ENGINE = InnoDB AUTO_INCREMENT = 1 DEFAULT CHARSET = utf8;